package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's claims, newest first, each with its status log and its comments and whether it is deferred on the sheet's today; given
 *  an as-of date, as they stood at the end of it, with their logs and comments then and deferred on it. */
public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, ClaimRepository repository,
            ClaimLogRepository logs, ClaimCommentRepository comments, SheetRepository sheets,
            ObjectResponse<List<ClaimResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        Map<Long, List<String>> lines = logs.lines(id, end);
        Map<Long, List<String>> said = comments.lines(id, end);
        var today = end != null ? end : sheets.today(id);
        List<Claim> claims = end != null ? repository.listAsOf(id, end) : repository.list(id);
        response.send(claims.stream()
                .map(c -> ClaimResponse.from(c, lines.getOrDefault(c.id(), List.of()), today,
                        said.getOrDefault(c.id(), List.of()))).toList());
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { claimsKey, useClaims } from './claims';
import { clearSelected, useSelectedClaims } from './selection';

type BulkSettleResult = { settled: number; refused: number };

/** The button that settles every selected claim together, by the signed-in user. The server settles each that can
 *  be settled, in list order and by the rules of settling one (a clerk's settle that leaves it PENDING counts as
 *  settled), and leaves the rest as they are; the bar then shows how many were settled and how many refused. */
function BulkSettle({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const claims = useClaims(sheetId).data ?? [];
  const chosen = useSelectedClaims(sheetId);
  const ids = claims.filter((c) => chosen.has(c.id)).map((c) => c.id);
  const [result, setResult] = useState<BulkSettleResult | null>(null);
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const settle = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<BulkSettleResult>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-settle`, { user, claimIds }),
    onSuccess: async (r) => {
      clearSelected(sheetId);
      setResult(r);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not settle the selected claims.'),
    onSettled: once.done,
  });

  return (
    <p>
      <button
        type="button"
        data-testid="bulk-settle"
        disabled={settle.isPending}
        onClick={() => {
          setError('');
          setResult(null);
          if (ids.length === 0) {
            setError('Select the claims to settle.');
            return;
          }
          if (!once.start()) return;
          settle.mutate(ids);
        }}
      >
        Settle selected
      </button>
      {result && (
        <>
          {' '}Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{result.refused}</span>
        </>
      )}
      {error && (
        <span data-testid="bulk-settle-error" role="alert">
          {' '}{error}
        </span>
      )}
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 13, Component: BulkSettle });
